arguments.argument:
saveGameName = "";
saveGameName = get_save_filename("Save Files (*.tty)|*.tty", "");
if (saveGameName != ""){
    if (string_copy(saveGameName, string_length(saveGameName) - 5, 6) != ".tty"){
        saveGameName = saveGameName + ".tty";
    }
    game_save(saveGameName);
}
